          } on Object catch (error, stackTrace) {
            engine.reportHostError(
              'render: $error',
              kind: 'render',
              stack: '$stackTrace',
            );
            rethrow;
          }
          return ViewportReporter(
            onSize: (size) => engine.dispatchHostEvent('viewport', {
              'width': size.width,
              'height': size.height,

